255	// extractSessionIDFromPath extracts the UUID from a Pi session filename.
256	// Pattern: <timestamp>_<uuid>.jsonl → returns <uuid>
257	func extractSessionIDFromPath(path string) string {
258		if path == "" {
259			return ""
260		}
261		base := filepath.Base(path)
262		// Remove .jsonl extension
263		if len(base) > 6 && base[len(base)-6:] == ".jsonl" {
264			base = base[:len(base)-6]
265		}
266		// Find the UUID after the last underscore
267		for i := len(base) - 1; i >= 0; i-- {
268			if base[i] == '_' {
269				return base[i+1:]
270			}
271		}
272		return base
273	}
