211	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
212		if maxSize <= 0 {
213			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
214		}
215		var chunks [][]byte
216		for len(content) > 0 {
217			end := maxSize
218			if end > len(content) {
219				end = len(content)
220			}
221			chunks = append(chunks, content[:end])
222			content = content[end:]
223		}
224		return chunks, nil
225	}
226	
227	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
228		var data []byte
229		for _, chunk := range chunks {
230			data = append(data, chunk...)
231		}
232		return data, nil
233	}
