235	// GetTranscriptPosition returns the number of lines in the JSONL transcript.
236	// The CLI uses this value as the offset for ExtractModifiedFiles, so units
237	// must match: both use line count (consistent with Claude Code).
238	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
239		data, err := os.ReadFile(path)
240		if err != nil {
241			if os.IsNotExist(err) {
242				return 0, nil
243			}
244			return 0, err
245		}
246		return countLines(data), nil
247	}
