311		}
312	
313		active := resolveActiveBranch(data)
314	
315		content := skipLines(data, offset)
316	
317		var prompts []string
318		scanner := newJSONLScanner(content)
319		for scanner.Scan() {
320			var entry messageEntry
321			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
322				continue
323			}
324			if entry.Type != entryTypeMessage || entry.Message.Role != "user" {
325				continue
326			}
327			if active != nil && !active[entry.ID] {
328				continue
329			}
330	
331			var items []contentItem
332			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
333				continue
334			}
335	
336			for _, item := range items {
337				if item.Type == contentTypeText && item.Text != "" {
