63	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
64		data, err := os.ReadFile(sessionRef)
65		if err != nil {
66			return protocol.CompactTranscriptResponse{}, fmt.Errorf("failed to read transcript: %w", err)
67		}
68	
69		compacted, err := compactTranscriptBytes(data)
70		if err != nil {
71			return protocol.CompactTranscriptResponse{}, err
72		}
73	
74		return protocol.CompactTranscriptResponse{
75			Transcript: base64.StdEncoding.EncodeToString(compacted),
76		}, nil
77	}
78	
79	func compactTranscriptBytes(data []byte) ([]byte, error) {
80		active := resolveActiveBranch(data)
81		results, err := collectCompactToolResults(data, active)
82		if err != nil {
83			return nil, err
84		}
85	
86		cliVersion := compactCLIVersion()
87		var buf bytes.Buffer
88	
89		scanner := newJSONLScanner(data)
90		for scanner.Scan() {
91			var entry messageEntry
92			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
93				continue
94			}
95			if entry.Type != entryTypeMessage {
96				continue
97			}
98			if active != nil && !active[entry.ID] {
99				continue
100			}
101	
102			switch entry.Message.Role {
103			case "user":
104				content := compactUserContent(entry.Message.Content)
105				if len(content) == 0 {
106					continue
107				}
108				if err := writeCompactTranscriptLine(&buf, compactTranscriptLine{
109					V:          1,
110					Agent:      compactTranscriptAgent,
111					CLIVersion: cliVersion,
112					Type:       "user",
113					TS:         entry.Timestamp,
114					Content:    content,
115				}); err != nil {
116					return nil, err
117				}
118	
119			case "assistant":
120				content := compactAssistantContent(entry.Message.Content, results)
121				if len(content) == 0 {
122					continue
123				}
124				line := compactTranscriptLine{
125					V:          1,
126					Agent:      compactTranscriptAgent,
127					CLIVersion: cliVersion,
128					Type:       "assistant",
129					TS:         entry.Timestamp,
130					ID:         entry.ID,
131					Content:    content,
132				}
133				if entry.Message.Usage != nil {
134					line.InputTokens = entry.Message.Usage.Input
135					line.OutputTokens = entry.Message.Usage.Output
136				}
137				if err := writeCompactTranscriptLine(&buf, line); err != nil {
138					return nil, err
139				}
140			}
141		}
142		if err := scanner.Err(); err != nil {
143			return nil, fmt.Errorf("scan transcript: %w", err)
144		}
145		if buf.Len() == 0 {
146			return nil, errors.New("compact transcript produced no output")
147		}
148		return buf.Bytes(), nil
149	}
150	
151	func compactUserContent(raw json.RawMessage) []compactUserTextBlock {
152		if text := decodeCompactString(raw); text != "" {
153			return []compactUserTextBlock{{Text: text}}
154		}
155	
156		var items []contentItem
157		if err := json.Unmarshal(raw, &items); err != nil {
158			return nil
159		}
160	
161		blocks := make([]compactUserTextBlock, 0, len(items))
162		for _, item := range items {
163			if item.Type == contentTypeText && item.Text != "" {
164				blocks = append(blocks, compactUserTextBlock{Text: item.Text})
165			}
166		}
167		return blocks
168	}
169	
170	func compactAssistantContent(raw json.RawMessage, results map[string]compactToolResultJSON) []any {
171		if text := decodeCompactString(raw); text != "" {
172			return []any{compactAssistantTextBlock{Type: contentTypeText, Text: text}}
173		}
174	
175		var items []contentItem
176		if err := json.Unmarshal(raw, &items); err != nil {
177			return nil
178		}
179	
180		blocks := make([]any, 0, len(items))
181		for _, item := range items {
182			switch item.Type {
183			case contentTypeText:
184				if item.Text != "" {
185					blocks = append(blocks, compactAssistantTextBlock{
186						Type: contentTypeText,
187						Text: item.Text,
188					})
189				}
190			case "toolCall":
191				block := compactAssistantToolUseBlock{
192					Type:  "tool_use",
193					ID:    item.ID,
194					Name:  normalizeCompactToolName(item.Name),
195					Input: decodeCompactInput(item.Arguments),
196				}
